// Shared with Achille's website chat, so the app and the website behave
// alike. Generated by scripts/sync-shared.mjs: do not edit it here.

// Human-answered chat (configuration mode "human", the ticketing chat channel).
// A person replies, possibly minutes later and possibly after the visitor left,
// so instead of endless typing dots the widget says where the reply will land,
// and asks for an email the reply can also go to.

// Whether an email is on file comes from the server (email_known), not from a
// Shopify identity merely being sent: the server sets the email itself when
// the signature verifies, and a tampered or expired identity gives none.
export interface EmailCardState {
  // email_known from the last poll: null until a poll answered (and always for
  // backends that do not send it).
  emailKnown: boolean | null;
  // The visitor typed an email in the pre-chat form.
  formEmail: boolean;
  // The visitor closed the card (remembered per widget key) or just gave
  // their email.
  dismissed: boolean;
  saved: boolean;
  hasVisitorMessage: boolean;
  // Offline, the email is asked before the first message instead.
  offline: boolean;
}

export function shouldShowEmailCard(state: EmailCardState): boolean {
  return (
    state.hasVisitorMessage &&
    !state.offline &&
    state.emailKnown === false &&
    !state.formEmail &&
    !state.dismissed &&
    !state.saved
  );
}

// Business hours: the configuration says whether people are there now
// (`online`) and how soon they usually answer (`wait_time`). Read at load
// only. null when the backend sends no `online` (the Shop Assistant).
export type WaitTime = "few_minutes" | "few_hours" | null;

export interface Availability {
  online: boolean;
  waitTime: WaitTime;
}

export function readAvailability(config: { online?: unknown; wait_time?: unknown }): Availability | null {
  if (typeof config.online !== "boolean") return null;
  const waitTime =
    config.online && (config.wait_time === "few_minutes" || config.wait_time === "few_hours")
      ? config.wait_time
      : null;
  return { online: config.online, waitTime };
}

export interface PresenceStrings {
  presenceMinutes: string;
  presenceHours: string;
  presenceOnline: string;
  presenceOffline: string;
}

// The header's subtitle next to the presence dot.
export function presenceText(strings: PresenceStrings, availability: Availability): string {
  if (!availability.online) return strings.presenceOffline;
  if (availability.waitTime === "few_minutes") return strings.presenceMinutes;
  if (availability.waitTime === "few_hours") return strings.presenceHours;
  return strings.presenceOnline;
}

export interface StatusStrings {
  sentStatus: string;
  sentStatusWithEmail: string;
  sentStatusMinutes: string;
  sentStatusMinutesWithEmail: string;
  sentStatusHours: string;
  sentStatusHoursWithEmail: string;
  offlineStatus: string;
}

// The line shown under the visitor's message while a reply is pending.
export function awaitingStatusText(
  strings: StatusStrings,
  availability: Availability | null,
  emailKnown: boolean
): string {
  if (availability && !availability.online) return strings.offlineStatus;
  const waitTime = availability?.waitTime ?? null;
  if (waitTime === "few_minutes") return emailKnown ? strings.sentStatusMinutesWithEmail : strings.sentStatusMinutes;
  if (waitTime === "few_hours") return emailKnown ? strings.sentStatusHoursWithEmail : strings.sentStatusHours;
  return emailKnown ? strings.sentStatusWithEmail : strings.sentStatus;
}

// On a chat whose AI is on, the AI starts writing (the poll's `typing`) a
// second or two after the visitor's message went out. Until then the dots
// stay, not the line saying the team will answer: that line only shows once
// the wait is over and the AI is still not writing.
export const AI_START_GRACE_MS = 10_000;

export interface SentMessage {
  aiEnabled: boolean;
  // The guided conversation's hand-over the message carried, if any.
  route: "ai" | "team" | null;
  // A cached answer already replied (the POST's `answer`).
  answered: boolean;
}

// Whether the AI is about to answer a message that just went out.
export function awaitsAi(message: SentMessage): boolean {
  return message.aiEnabled && message.route !== "team" && !message.answered;
}

export interface OfflineEmailState {
  offline: boolean;
  hasSession: boolean;
  // A Shopify customer identity rides with the messages.
  hasIdentity: boolean;
  // email_known from the last poll (null until one answered).
  emailKnown: boolean | null;
  formEmail: boolean;
  saved: boolean;
}

// Offline, the reply can only go by email: the composer is replaced by the
// email form until one is on file. A new conversation has none yet, unless a
// Shopify identity rides along: its first message goes straight away and the
// server takes the email once the signature verifies. An existing one has an
// email once the poll says so (so a failed identity lands here too), and keeps
// the composer until that poll answers.
export function needsOfflineEmail(state: OfflineEmailState): boolean {
  if (!state.offline || state.formEmail || state.saved) return false;
  return state.hasSession ? state.emailKnown === false : !state.hasIdentity;
}

export interface SeenState {
  humanMode: boolean;
  visibilityState: string;
  // Inline and modal embeds: the chat is on the page while mounted.
  embedded: boolean;
  // Floating embed: the bubble is open (the loader's open/closed messages).
  panelOpen: boolean;
}

// Whether the poll tells the server the visitor has the conversation in front
// of them (seen=1). The server emails an agent's reply the visitor has not
// seen, so a chat that is loaded but hidden (closed bubble, background tab)
// must not count.
export function sendsSeen(state: SeenState): boolean {
  return (
    state.humanMode &&
    state.visibilityState === "visible" &&
    (state.embedded || state.panelOpen)
  );
}

// Deliberately loose: the server has the final say (422), this only keeps the
// submit button off until the input looks like an address.
export function looksLikeEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

export interface NamedMessage {
  from_agent: boolean;
  sender_name: string | null;
}

// An agent's name heads each run of consecutive replies from that agent, like
// any messaging app, instead of repeating on every bubble.
export function showsSenderName(messages: readonly NamedMessage[], index: number): boolean {
  const message = messages[index];
  if (!message?.from_agent || !message.sender_name) return false;
  const previous = messages[index - 1];
  return !(previous?.from_agent && previous.sender_name === message.sender_name);
}
